import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{"title":"Architecture Overview"},"headers":[],"relativePath":"design/architecture.md","filePath":"design/architecture.md"}'),r={name:"design/architecture.md"};function o(i,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Lattice is composed of three core components:</p><table tabindex="0"><thead><tr><th>Component</th><th>Entry Point</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Lattice Agent</strong></td><td><code>cmd/lattice</code></td><td>Edge node: WireGuard tunnel, NATS signaling, ICE/LRP</td></tr><tr><td><strong>LatticeD</strong></td><td><code>cmd/latticed</code></td><td>All-in-one control plane: NATS + SQLite + API + UI</td></tr><tr><td><strong>Manager</strong></td><td><code>cmd/manager</code></td><td>Kubernetes operator: reconciles CRDs</td></tr></tbody></table><h2 id="transport-layer" tabindex="-1">Transport Layer <a class="header-anchor" href="#transport-layer" aria-label="Permalink to &quot;Transport Layer&quot;">​</a></h2><p>Each peer-to-peer connection goes through a state machine:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Probing → ICEReady / LRPReady → Failed → Closed</span></span></code></pre></div><p>ICE (direct P2P) and LRP (relay fallback) race in parallel. Whichever establishes first wins. The connection upgrades from LRP to ICE transparently when a direct path becomes available.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Peer A                                    Peer B</span></span>
<span class="line"><span>  │  ── NATS signal ──────────────────────▶  │</span></span>
<span class="line"><span>  │  ◀── NATS signal ──────────────────────  │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  │  ── ICE probe ─────────────────────────▶ │  ← races with LRP</span></span>
<span class="line"><span>  │  ── LRP connect ───────────▶ Relay ────▶ │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  └─────────── WireGuard data ───────────────┘</span></span></code></pre></div><h2 id="policy-enforcement" tabindex="-1">Policy Enforcement <a class="header-anchor" href="#policy-enforcement" aria-label="Permalink to &quot;Policy Enforcement&quot;">​</a></h2><p><code>PolicyEnforcer</code> interface in <code>internal/agent/provision/provisioner.go</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SelectEnforcerMode()</span></span>
<span class="line"><span>  ├── Linux 5.10+ &amp;&amp; EDITION=pro → eBPF TC on wf0 TUN interface</span></span>
<span class="line"><span>  └── default                   → iptables</span></span></code></pre></div><p>Community edition always uses iptables. Pro edition uses eBPF when kernel supports it, with automatic fallback to iptables.</p><h2 id="agent-sandbox" tabindex="-1">Agent Sandbox <a class="header-anchor" href="#agent-sandbox" aria-label="Permalink to &quot;Agent Sandbox&quot;">​</a></h2><p>The sandbox provides a <strong>zero-privilege</strong> alternative to the regular node:</p><ul><li>Regular node: kernel TUN (<code>wf0</code>), requires <code>CAP_NET_ADMIN</code></li><li>Sandbox: gVisor <code>pkg/tcpip</code> + <code>TUNAdapter</code>, runs as any user</li></ul><p>See <a href="/design/sandbox">Sandbox Architecture</a> for the detailed design.</p><h2 id="signal-flow" tabindex="-1">Signal Flow <a class="header-anchor" href="#signal-flow" aria-label="Permalink to &quot;Signal Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LatticeD (NATS broker)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── lattice.signals.peers.&lt;PeerID&gt;  ← peer signaling</span></span>
<span class="line"><span>    ├── lattice.audit.flow              ← Pro: NATS flow audit</span></span>
<span class="line"><span>    └── lattice.config.&lt;PeerID&gt;         ← peer config push</span></span></code></pre></div><h2 id="enrollment-network-management-shipped-2026-09" tabindex="-1">Enrollment &amp; Network Management (shipped 2026-09) <a class="header-anchor" href="#enrollment-network-management-shipped-2026-09" aria-label="Permalink to &quot;Enrollment &amp; Network Management (shipped 2026-09)&quot;">​</a></h2><p>Capabilities verified on real devices (cloud control plane + macOS/iOS clients + container nodes):</p><table tabindex="0"><thead><tr><th>Capability</th><th>How it works</th><th>Reference</th></tr></thead><tbody><tr><td><strong>Zero-trust enrollment</strong></td><td>Client generates its WireGuard keypair locally; the private key never leaves the device. Registration with an enrollment token lands in <code>pending</code> when the workspace requires approval; the admin approves in the dashboard before the netmap is served. Re-registering with a different pubkey is rejected.</td><td><a href="/adr/0003-peer-enrollment-approval-and-client-side-keygen">ADR-0003</a></td></tr><tr><td><strong>Join QR</strong></td><td>Dashboard token page renders <code>lattice://join?server=&lt;dashboard origin&gt;&amp;token=&lt;token&gt;</code>; Apple clients scan it to enroll without typing. The <code>server</code> embedded is the dashboard address the phone is browsing — it must be an address the device can reach.</td><td><code>frontend/src/pages/manage/tokens</code></td></tr><tr><td><strong>Netmap convergence</strong></td><td>Netmap is pushed over NATS and re-pulled every <code>netmap-poll-interval</code> (default 30s); peers carry endpoints, relay info and allowed IPs.</td><td><code>internal/server/reconcilers/netmap_builder.go</code></td></tr><tr><td><strong>LatticeDNS</strong></td><td>Optional built-in <code>*.lattice</code> DNS responder in the engine (<code>enable-dns</code>), so peers resolve names over the overlay.</td><td><a href="/latticedns-technical">LatticeDNS technical notes</a></td></tr><tr><td><strong>Subnet routes / exit node</strong></td><td>A peer can advertise subnets (CIDR-validated) so non-agent-installable devices reach the mesh through a gateway node.</td><td>spec 2026-09-14-exit-node-subnet-route</td></tr><tr><td><strong>Publish gateway</strong></td><td>A mesh member can expose an internal service to the public internet via an ingress gateway (<code>ingress-addr</code>), with share links managed in the dashboard.</td><td>commit 3dfe10dd</td></tr><tr><td><strong>Per-peer stats &amp; approvals UI</strong></td><td>Device detail shows per-peer latency/traffic; enrollment approvals are managed from the device list (macOS client + dashboard).</td><td>commits 59079d39, 95cb08d0</td></tr><tr><td><strong>Apple clients</strong></td><td>macOS app runs the Go engine inside a Network Extension (real mesh member, host can bind on the overlay); iOS app with QR join; both ship tunnel logs for diagnostics.</td><td>spec 2026-09-13-apple-clients</td></tr></tbody></table>`,21)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
